import{_ as e,o as r,c as n,a2 as o}from"./chunks/framework.D8Tso2Ul.js";const s="/manual/img/bandeja-entrada/inicio.png",t="/manual/img/bandeja-entrada/nuevo-mensaje.png",b=JSON.parse('{"title":"Bandeja de Entrada","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/bandeja-entrada.md","filePath":"modulos/bandeja-entrada.md"}'),i={name:"modulos/bandeja-entrada.md"};function l(d,a,c,u,p,g){return r(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="bandeja-de-entrada" tabindex="-1">Bandeja de Entrada <a class="header-anchor" href="#bandeja-de-entrada" aria-label="Permalink to &quot;Bandeja de Entrada&quot;">​</a></h1><p>La <strong>Bandeja de Entrada</strong> es el sistema de mensajería interno de la plataforma. Funciona como un correo simplificado entre las personas de una misma obra: sirve para coordinar, avisar y dejar registro de comunicaciones de seguridad, sin salir del sistema ni depender de WhatsApp o correos personales.</p><h2 id="entrar-a-la-bandeja" tabindex="-1">Entrar a la Bandeja <a class="header-anchor" href="#entrar-a-la-bandeja" aria-label="Permalink to &quot;Entrar a la Bandeja&quot;">​</a></h2><p>En el menú lateral, haz clic en <strong>Bandeja de Entrada</strong> (o <strong>Inbox</strong>). Si tienes mensajes sin leer, lo verás reflejado también en tu <a href="/manual/modulos/dashboard.html">Dashboard</a>.</p><p><img src="'+s+'" alt="Bandeja de Entrada con las carpetas Recibidos, Enviados y Archivados"></p><h2 id="organizacion-de-los-mensajes" tabindex="-1">Organización de los mensajes <a class="header-anchor" href="#organizacion-de-los-mensajes" aria-label="Permalink to &quot;Organización de los mensajes&quot;">​</a></h2><p>Los mensajes se ordenan en tres carpetas, que cambias con las pestañas de la parte superior:</p><ul><li><strong>Recibidos</strong> — los mensajes que te llegaron.</li><li><strong>Enviados</strong> — los que tú enviaste.</li><li><strong>Archivados</strong> — los que guardaste para sacarlos de la bandeja sin borrarlos.</li></ul><p>Dentro de <strong>Recibidos</strong> puedes filtrar entre <strong>TODOS</strong> y <strong>NO LEÍDOS</strong> para enfocarte en lo pendiente. También tienes un <strong>buscador</strong> para encontrar un mensaje por su contenido.</p><h2 id="enviar-un-mensaje-nuevo" tabindex="-1">Enviar un mensaje nuevo <a class="header-anchor" href="#enviar-un-mensaje-nuevo" aria-label="Permalink to &quot;Enviar un mensaje nuevo&quot;">​</a></h2><ol><li>Haz clic en el botón <strong>Nuevo Mensaje</strong>.</li><li>Completa el formulario: <ul><li><strong>Obra</strong> <em>(obligatorio)</em> — elige la obra en cuyo contexto envías el mensaje. Solo puedes escribir a personas de una obra a la que perteneces.</li><li><strong>Destinatarios</strong> — selecciona a quién va dirigido. Puedes buscar por <strong>nombre, cargo o RUT</strong> para encontrarlos rápido.</li><li><strong>Prioridad</strong> — marca la urgencia del mensaje.</li><li><strong>Asunto</strong> <em>(obligatorio)</em> — el tema del mensaje.</li><li><strong>Mensaje</strong> <em>(obligatorio)</em> — el contenido.</li></ul></li><li>Haz clic en <strong>Enviar</strong>.</li></ol><p><img src="'+t+'" alt="Ventana de Nuevo Mensaje con la selección de obra y destinatarios"></p><blockquote><p>💡 La <strong>Obra</strong> es obligatoria porque la mensajería está organizada por proyecto. Esto mantiene cada comunicación asociada a su contexto y a las personas correctas.</p></blockquote><h2 id="leer-archivar-y-eliminar" tabindex="-1">Leer, archivar y eliminar <a class="header-anchor" href="#leer-archivar-y-eliminar" aria-label="Permalink to &quot;Leer, archivar y eliminar&quot;">​</a></h2><p>Al abrir un mensaje verás su contenido completo. Desde ahí puedes:</p><ul><li><strong>Archivar</strong> el mensaje (lo mueve a la carpeta Archivados).</li><li><strong>Eliminar</strong> el mensaje.</li></ul><p>Los mensajes no leídos se destacan para que sepas qué te falta revisar.</p><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>No puedo enviar un mensaje: me dice que no pertenezco a ninguna obra.</strong> La mensajería requiere que tú y el destinatario estén en una misma obra. Si no perteneces a ninguna, pide a un administrador que te asigne a la obra correspondiente.</p><p><strong>No encuentro a la persona a la que quiero escribir.</strong> Solo aparecen los destinatarios de la <strong>obra seleccionada</strong>. Verifica que elegiste la obra correcta y que la persona esté asignada a ella. Usa el buscador por nombre, cargo o RUT.</p><p><strong>¿Cuál es la diferencia entre archivar y eliminar?</strong><strong>Archivar</strong> guarda el mensaje en la carpeta Archivados (lo conservas pero sale de Recibidos). <strong>Eliminar</strong> lo borra. Si dudas, archiva.</p><p><strong>¿Para qué sirve la prioridad?</strong> Ayuda al destinatario a identificar qué mensajes son urgentes. Úsala con criterio: si todo es &quot;alta prioridad&quot;, deja de ser útil.</p><p><strong>¿Esto reemplaza al correo o WhatsApp de la obra?</strong> Para las comunicaciones de seguridad, sí es recomendable: queda <strong>registrado dentro de la plataforma</strong>, asociado a la obra y a las personas, lo que aporta trazabilidad que un chat personal no tiene.</p>',23)])])}const h=e(i,[["render",l]]);export{b as __pageData,h as default};
